contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount <= address(this).balance);
        uint256 balBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 ethBefore = address(c).balance;

        bool reverted;
        c.addToBalance{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(!reverted && c.getBalance(address(this)) == balBefore + amount && address(c).balance == ethBefore + amount);
    }

    receive() external payable {}
}

